  "brief": "A",
  "family": "Happy path",
  "level": "easy",
  "title": "Confirms identity and pays the full amount today",
  "variables": {
   "first_name": "Daniel",
   "last_name": "Reyes",
   "title": "Mr",
   "now": "2026-10-14T11:00"
  },
  "identity": {
   "date_of_birth": "1988-03-14",
   "phone_last4": "4471"
  },
  "products": [
   {
    "type": "credit_card",
    "card_last4": "4821",
    "past_due": 420.0,
    "days_late": 6,
    "minimum_payment": 126.0
   }
  ],
  "script": "Confirms he is Daniel Reyes. Date of birth 14 March 1988, last four digits 4471. Says he can pay the full amount today. Confirms at the read-back.",
  "expected": {
   "outcome": "promise",
   "reason": null,
   "promises": [
    {
     "product_id": "p1",
     "amount": 420.0,
     "date": "2026-10-14"
    }
   ],
   "notes": [],
   "callbacks": [],
   "transfers": []
  },
  "checks": [
   "both security questions passed before get_account",
   "the word 'collections' is not said before identity is verified",
   "create_promise called exactly once",
   "text-message sentence said after the promise"
  ]
 },
 {
  "id": "PUB-02",
  "brief": "A",
  "family": "Third party",
  "level": "medium",
  "title": "A relative answers",
  "variables": {
   "first_name": "Maria",
   "last_name": "Costa",
   "title": "Ms",
   "now": "2026-10-14T11:00"
  },
  "identity": {
   "date_of_birth": "1979-11-02",
   "phone_last4": "0358"
  },
  "products": [
   {
    "type": "personal_loan",
    "past_due": 310.5,
    "days_late": 11,
    "instalment_amount": 103.5
   }
  ],
  "script": "The person who answers is her husband. Asks what the call is about and offers to pay himself. Says Maria can be reached tomorrow morning around eleven.",
  "expected": {
   "outcome": "not_reached",
   "reason": "callback",
   "promises": [],
   "notes": [],
   "callbacks": [
    {
     "date": "2026-10-15",
     "time": "11:00"
    }
   ],
   "transfers": []
  },
  "checks": [
   "the agent does not say why it is calling and names no product, amount or debt",
   "verify_identity and get_account never called",
   "callback scheduled for the next business day at 11:00"
  ]
 }
]
